{"code":"import pandas as pd, statsmodels.formula.api as smf
D=pd.read_csv('data/explore.csv'); xs=[c for c in D if c not in ['id','lab','tensile_mpa']]
for x in xs:
 m=smf.ols(f'tensile_mpa ~ {x} + C(lab)',D).fit()
 print(x, round(m.params[x],3), round(m.pvalues[x],5), round(m.rsquared,3))
"}
